LOCK TABLES `joom_tb_edital` WRITE;
/*!40000 ALTER TABLE `joom_tb_edital` DISABLE KEYS */;
INSERT INTO `joom_tb_edital` (`id`, `state`, `ordering`, `checked_out`, `checked_out_time`, `created_by`, `modified_by`, `no_edital`, `ds_edital`, `dt_abertura`, `dt_encerramento`, `dt_publicacao`, `co_edital_municipio_consorcio`, `tp_edital`, `co_edital_adesao`, `tp_esfera_solicitante`, `co_grupos`) VALUES (1,1,1,NULL,NULL,139,139,'Formulário de teste','tetando formulario','2026-10-01 19:26:00','2026-11-07 19:26:00','2026-10-01 19:26:00',NULL,'formulario',NULL,NULL,NULL),(18,1,0,139,'2026-11-01 13:39:59',0,0,'Coleta MIR - TEDs (MIR)','<p>Instrumento para coleta de dados de forma territorializada dos Termos de Execução Descentralizada (TEDs) celebrados pelo Ministério da Igualdade Racial (MIR).</p><p><strong>Perfis de preenchimento:</strong></p><ul><li><strong>Identificação, responsáveis, enquadramento, modalidade de resposta e fiscalização:</strong> servidor do MIR</li><li><strong>Execução e projetos:</strong> gestor do TED na Unidade Descentralizada (atualização periódica), em formulário próprio (gestor), a partir do instrumento em \"Meus instrumentos\", com o acesso da sua UG liberado pelo MIR</li><li><strong>Atividades e beneficiários:</strong> responsável por cada projeto, identificado pelo CPF na lista de projetos do gestor do TED, em formulário próprio (execução), um preenchimento por atividade</li></ul><p>A sugestão de periodicidade de atualização é trimestral.</p><p>Campos marcados como automáticos serão preenchidos a partir do Transferegov.br / SIAFI / Siorg quando a integração estiver disponível; até lá, preencha manualmente.</p>','2026-10-31 00:00:00','2027-12-31 23:59:59','2026-10-31 00:00:00',NULL,'formulario',NULL,NULL,'10'),(19,1,0,NULL,NULL,0,0,'Coleta MIR - TEDs (gestor)','<p>Atualização periódica da execução dos Termos de Execução Descentralizada (TEDs) celebrados pelo MIR.</p><p><strong>Quem preenche:</strong> gestor do TED na Unidade Descentralizada: forma de execução, contrapartida e os projetos/ações apoiados, com seus responsáveis. Identificação, responsáveis, enquadramento e fiscalização são preenchidos pelo servidor do MIR em formulário próprio.</p><p>Ao enviar, cada projeto aparece em \"Meus instrumentos\" para o responsável informado (pelo CPF), que registra no formulário de execução as atividades e os beneficiários.</p><p>A sugestão de periodicidade de atualização é trimestral.</p>','2026-10-31 00:00:00','2027-12-31 23:59:59','2026-10-31 00:00:00',NULL,'formulario',NULL,NULL,NULL),(20,1,0,NULL,NULL,0,0,'Coleta MIR - Convênios (MIR)','<p>Instrumento para coleta de dados de forma territorializada dos convênios, contratos de repasse e termos de fomento e de colaboração celebrados pelo Ministério da Igualdade Racial (MIR), na qualidade de concedente.</p><p>O Coleta MIR não substitui o registro dos atos de execução, acompanhamento e fiscalização, nem a prestação de contas, exigidos no Transferegov.br (Decreto nº 11.531/2023); seu propósito é complementar esses registros com informações territorializadas.</p><p><strong>Perfis de preenchimento:</strong></p><ul><li><strong>Identificação, responsáveis, enquadramento, modalidade de resposta e fiscalização:</strong> servidor do MIR (concedente)</li><li><strong>Execução e projetos:</strong> convenente (atualização periódica), em formulário próprio (convenente), a partir do instrumento em \"Meus instrumentos\", com o acesso da sua CNPJ liberado pelo MIR</li><li><strong>Atividades e beneficiários:</strong> responsável por cada projeto, identificado pelo CPF na lista de projetos do convenente, em formulário próprio (execução), um preenchimento por atividade</li></ul><p>A sugestão de periodicidade de atualização é trimestral.</p><p>Campos marcados como automáticos serão preenchidos a partir do Transferegov.br / SIAFI / Siorg quando a integração estiver disponível; até lá, preencha manualmente.</p>','2026-10-31 00:00:00','2027-12-31 23:59:59','2026-10-31 00:00:00',NULL,'formulario',NULL,NULL,'10'),(21,1,0,NULL,NULL,0,0,'Coleta MIR - Convênios (convenente)','<p>Atualização periódica da execução dos convênios celebrados pelo MIR, na qualidade de concedente.</p><p><strong>Quem preenche:</strong> convenente: forma de execução, contrapartida, bens e os projetos/ações apoiados, com seus responsáveis. Identificação, responsáveis, enquadramento e fiscalização são preenchidos pelo servidor do MIR em formulário próprio.</p><p>Ao enviar, cada projeto aparece em \"Meus instrumentos\" para o responsável informado (pelo CPF), que registra no formulário de execução as atividades e os beneficiários.</p><p>A sugestão de periodicidade de atualização é trimestral.</p>','2026-10-31 00:00:00','2027-12-31 23:59:59','2026-10-31 00:00:00',NULL,'formulario',NULL,NULL,NULL),(22,1,0,NULL,NULL,0,0,'Coleta MIR - TEDs (execução)','<p>Registro das atividades executadas e dos beneficiários alcançados nos Termos de Execução Descentralizada (TEDs) celebrados pelo MIR: um preenchimento por atividade.</p><p><strong>Quem preenche:</strong> o responsável por cada projeto, vinculado pelo CPF na lista de projetos do gestor do TED, ou o próprio gestor, quando a Unidade Descentralizada executa diretamente. O preenchimento começa pelo projeto, em \"Meus instrumentos\". O TED, o período e o projeto vêm definidos pelo gestor.</p>','2026-10-31 00:00:00','2027-12-31 23:59:59','2026-10-31 00:00:00',NULL,'formulario',19,NULL,NULL),(23,1,0,NULL,NULL,0,0,'Coleta MIR - Convênios (execução)','<p>Registro das atividades executadas e dos beneficiários alcançados nos convênios celebrados pelo MIR: um preenchimento por atividade.</p><p><strong>Quem preenche:</strong> o responsável por cada projeto, vinculado pelo CPF na lista de projetos do convenente, ou o próprio convenente, quando executa diretamente. O preenchimento começa pelo projeto, em \"Meus instrumentos\". O convênio, o período e o projeto vêm definidos pelo convenente.</p>','2026-10-31 00:00:00','2027-12-31 23:59:59','2026-10-31 00:00:00',NULL,'formulario',21,NULL,NULL);
